cd build && python -c "
import numpy as np
L=open('opt3.xyz').read().split(chr(10))
n=int(L[0]); X=np.array([[float(x) for x in l.split()[1:4]] for l in L[2:2+n]])
S=[l.split()[0] for l in L[2:2+n]]
for i in [1,2,3,4,5,26,35,38]: print(S[i],i, round(np.linalg.norm(X[i]-X[0]),3))
cov=dict(H=0.31,C=0.76,N=0.71,O=0.66,F=0.57,Rh=1.42)
bonds=set()
for i in range(n):
  for j in range(i+1,n):
    if np.linalg.norm(X[i]-X[j])<1.3*(cov[S[i]]+cov[S[j]]): bonds.add((i,j))
print(len(bonds))
# compare with opt2
L2=open('opt2.xyz').read().split(chr(10))
X2=np.array([[float(x) for x in l.split()[1:4]] for l in L2[2:2+n]])
b2=set()
for i in range(n):
  for j in range(i+1,n):
    if np.linalg.norm(X2[i]-X2[j])<1.3*(cov[S[i]]+cov[S[j]]): b2.add((i,j))
print('diff',bonds^b2)
" && cp opt3.xyz ../answer.xyz && cd .. && head -3 answer.xyz && wc -l answer.xyz
